import{_ as e,o as i,c as a,an as n}from"./chunks/framework.7rAndvnY.js";const l="/EegFun.jl/dev/tutorials/signal_example_sampling.png",u=JSON.parse('{"title":"Signal Example — Sampling & Reconstruction","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/teaching/signal_processing/signal_example_sampling.md","filePath":"tutorials/teaching/signal_processing/signal_example_sampling.md","lastUpdated":null}'),s={name:"tutorials/teaching/signal_processing/signal_example_sampling.md"};function r(o,t,h,g,d,p){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="Signal-Example-—-Sampling-and-Reconstruction" tabindex="-1">Signal Example — Sampling &amp; Reconstruction <a class="header-anchor" href="#Signal-Example-—-Sampling-and-Reconstruction" aria-label="Permalink to &quot;Signal Example — Sampling &amp; Reconstruction {#Signal-Example-—-Sampling-and-Reconstruction}&quot;">​</a></h1><p>Interactive demonstration of the <strong>Nyquist–Shannon sampling theorem</strong>.</p><p>This demo shows how sampling rate affects the reconstruction of a sine wave.</p><img src="'+l+`" alt="Signal Example 1"><h2 id="What-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#What-it-shows" aria-label="Permalink to &quot;What it shows {#What-it-shows}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Feature</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">Original signal</td><td style="text-align:right;">A &quot;continuous&quot; sine wave at the chosen frequency</td></tr><tr><td style="text-align:right;">Sampled points</td><td style="text-align:right;">The discrete samples taken at the chosen sampling rate</td></tr><tr><td style="text-align:right;">Linear reconstruction</td><td style="text-align:right;">Straight-line interpolation between samples</td></tr><tr><td style="text-align:right;">Sinc reconstruction</td><td style="text-align:right;"><a href="https://en.wikipedia.org/wiki/Whittaker%E2%80%93Shannon_interpolation_formula" target="_blank" rel="noreferrer">Whittaker–Shannon</a> (ideal) interpolation</td></tr></tbody></table><p><strong>Linear reconstruction</strong> connects adjacent samples with straight lines. It is simple but introduces distortion — particularly at low sampling rates relative to the signal frequency.</p><p><strong>Sinc reconstruction</strong> uses the <a href="https://en.wikipedia.org/wiki/Whittaker%E2%80%93Shannon_interpolation_formula" target="_blank" rel="noreferrer">Whittaker–Shannon interpolation formula</a> to reconstruct the signal exactly (within the Nyquist limit).</p><p>When the sampling rate falls <strong>below</strong> twice the signal frequency, the signal cannot be recovered: the sampled waveform appears at the wrong frequency — a phenomenon known as <strong>aliasing</strong>. Modern EEG systems typically sample at 256–2048 Hz, which is far above the Nyquist limit for brain signals of interest (usually &lt; 100 Hz), ensuring faithful digitisation.</p><h2 id="Things-to-Try" tabindex="-1">Things to Try <a class="header-anchor" href="#Things-to-Try" aria-label="Permalink to &quot;Things to Try {#Things-to-Try}&quot;">​</a></h2><ul><li><p>Start with a sampling rate well above Nyquist (e.g. 10× the signal frequency) and observe that both methods agree with the original signal.</p></li><li><p>Gradually reduce the sampling rate toward and then below the Nyquist limit (~2× the signal frequency) to show reconstruction breakdown and <strong>aliasing</strong>.</p></li><li><p>Enable both reconstructions simultaneously to highlight the superiority of sinc interpolation near the Nyquist limit.</p></li></ul><h2 id="Controls" tabindex="-1">Controls <a class="header-anchor" href="#Controls" aria-label="Permalink to &quot;Controls {#Controls}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Control</th><th style="text-align:right;">Range</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">Duration</td><td style="text-align:right;">1–10 s</td><td style="text-align:right;">Length of the displayed signal</td></tr><tr><td style="text-align:right;">Signal Frequency</td><td style="text-align:right;">1–100 Hz</td><td style="text-align:right;">Frequency of the underlying sine wave</td></tr><tr><td style="text-align:right;">Phase Angle</td><td style="text-align:right;">−π to π</td><td style="text-align:right;">Phase offset of the sine wave</td></tr><tr><td style="text-align:right;">Sampling Rate</td><td style="text-align:right;">1–300 Hz</td><td style="text-align:right;">Number of samples per second</td></tr><tr><td style="text-align:right;">☐ Linear</td><td style="text-align:right;">—</td><td style="text-align:right;">Toggle linear interpolation overlay</td></tr><tr><td style="text-align:right;">☐ Sinc</td><td style="text-align:right;">—</td><td style="text-align:right;">Toggle sinc reconstruction overlay</td></tr></tbody></table><h2 id="See-Also" tabindex="-1">See Also <a class="header-anchor" href="#See-Also" aria-label="Permalink to &quot;See Also {#See-Also}&quot;">​</a></h2><ul><li><p>Luck, S. J. (2014). <em>An Introduction to the Event-Related Potential Technique</em> (2nd ed.). MIT Press. — Chapter 5 (Section: Amplifying, Filtering, and Digitizing the Signal, Figure 5.7)</p></li><li><p><a href="https://demonstrations.wolfram.com/SincInterpolationForSignalReconstruction/" target="_blank" rel="noreferrer">Sinc Interpolation for Signal Reconstruction (Wolfram Demonstrations)</a></p></li><li><p><a href="./signal_example_composition">Signal Example — Composition</a> — multi-signal composition and filtering</p></li><li><p><a href="./signal_example_dotproduct">Signal Example — Dot Product</a> — how the DFT detects frequencies</p></li></ul><h2 id="Code" tabindex="-1">Code <a class="header-anchor" href="#Code" aria-label="Permalink to &quot;Code {#Code}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EegFun</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">signal_example_sampling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>`,17)])])}const m=e(s,[["render",r]]);export{u as __pageData,m as default};
